import SparkMD5 from 'spark-md5';


/**
 * 图片压缩
 * @param file 文件
 * @param maxWidth 最大宽度
 * @param maxHeight 最大高度
 * @param quality 最大京都
 */
export function compressToWebP(file, maxWidth, maxHeight, quality = 0.7) {
    return new Promise((resolve, reject) => {
        const img: any = new Image();
        const reader = new FileReader();

        reader.onload = (event) => {
            img.src = event.target.result;
        };

        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');

            let width = img.width;
            let height = img.height;

            // 计算新的宽高比
            if (width > height) {
                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }
            } else {
                if (height > maxHeight) {
                    width *= maxHeight / height;
                    height = maxHeight;
                }
            }

            canvas.width = width;
            canvas.height = height;

            // 绘制图像到 canvas
            ctx.drawImage(img, 0, 0, width, height);

            const ext = file.name.split('.').pop();
            // 压缩图像并转换为 WebP 格式
            canvas.toBlob((blob) => {
                if (blob) {
                    resolve(blob);
                } else {
                    reject(new Error('压缩失败'));
                }
            }, `image/${ext}`, quality); // 设置 MIME 类型为 WebP
        };

        img.onerror = (error) => {
            reject(new Error('图片加载失败'));
        };

        reader.readAsDataURL(file);
    });
}


export const calculateFileHash = (file): Promise<string> => {
    // 创建 FileReader 对象来读取文件内容
    const reader = new FileReader();

    const result: any = new Promise((resolve, reject) => {
        // 读取文件完成后执行的回调函数
        reader.onload = function(event) {
            const fileContent = event.target.result; // 获取文件内容

            // 计算文件内容的 MD5 值
            const spark = new SparkMD5.ArrayBuffer();
            spark.append(fileContent);
            const md5 = spark.end();

            resolve(md5)
        };

        reader.onerror = reject;
    })

    // 读取文件内容
    reader.readAsArrayBuffer(file);

    return result;
}



export const svgContentUrl = (content: string) => {
    const svgContent = content;
    const blob = new Blob([svgContent], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    return url;
}


export const fileSizeText = (file) => {
    const fileSize = file.size;
    if (file.size < 1024 * 1024) {
        return (fileSize / 1024).toFixed(2) + ' KB'; // 小于 1 MB
    } else {
        return (fileSize / (1024 * 1024)).toFixed(2) + ' MB'; // 大于等于 1 MB
    }
}