import ajax from "@/utils/ajax";
import { compressToWebP } from "@/utils/file";
import { Message, Modal } from "@arco-design/web-react";
import { action, computed, observable, runInAction, makeObservable } from "mobx";
import file from "@/store/file";
import React from "react";



class Store {
    getList = file.getList


    @observable editData: any = null;
    @action setEditData = (data) => {
        this.editData = data;
    }
    @observable visible = false;
    @action setVisible = (bool) => {
        this.file = null;
        this.oldFile = null;
        this.visible = bool;
    }


    constructor() {
        makeObservable(this);
    }


    @computed get title(){
        return this.editData? `图片编辑` : `图片上传`
    }

    @observable compress = true;    // 是否压缩
    @action setCompress = (bool) => {
        this.compress = bool;
    }
    @observable maxWidth = 1028;    // 最大宽度
    @action setMaxWidth = (val) => {
        this.maxWidth = val;
    }
    @observable quality = 0.7;      // 压缩精度
    @action setQuality = (num) => {
        this.quality = num;
    }


    @observable fileName = "";
    @action setFileName = (val) => {
        this.fileName = val;
    }

    @observable name = "";
    @action setName = (val) => {
        this.name = val;
    }


    @observable isSvg = false;  // svg 不进行压缩

    @observable file = null;    // 上传的file
    @observable oldFile = null; // 压缩后的file 对象
    @action clearFile = () => { this.file = null }
    @action updateOldFile = async () => {
        if(this.file){
            if(!this.editData){
                this.fileName = this.file.name;
            }
            if(this.fileName.endsWith('.svg')){
                // 判断是否为SVG 图片
                this.compress = false;
                this.isSvg = true;
            }
            if(this.compress){
                this.oldFile = await compressToWebP(this.file, Math.max(this.maxWidth || 50), 1000000, this.quality);
            }else {
                this.oldFile = this.file;
            }
        }else {
            this.oldFile = null;
        }
    }
    @action setFile = (file) => {
        this.file = file;
    }


    @action previewUploadVerify = () => {
        const file = this.oldFile;
        // 校验文件类型
        if (!file.type.startsWith('image/')) {
            Message.error("只允许上传图片文件！")
            return;
        }
        // 校验文件大小
        if (file.size > 2 * 1024 * 1024) { // 2MB
            Message.error("文件大小不能超过 2MB！")
            return;
        }
    }



    handleFileChange = (event) => {
        const files = event.target.files;
        for (const file of files) {
            if (file.type.startsWith('image/')) {
                this.setFile(file);
            } else {
                Message.success("只允许上传图片文件！");
            }
        }
    }


    onClick() {
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = 'image/*'; // 限制只允许图片类型
        fileInput.style.display = 'none'; // 隐藏输入框

        fileInput.addEventListener('change', this.handleFileChange);
        // document.body.appendChild(fileInput); // 将输入框添加到文档中
        fileInput.click(); // 触发点击事件
        // document.body.removeChild(fileInput); // 点击后移除输入框
    }


    // 用户删除文件
    deleteFile(data: any){
        Modal.confirm({
            title: "删除确认",
            content: `请确认是否要删除 ${data.fileName} 文件`,
            onOk: () => {
                return ajax.post('/appfile/deleteFile', {
                    id: data.id
                }).then((res) => {
                    Message.success("删除成功");
                    this.getList();
                })
            }
        })
    }

    //  用户粘贴图片
    handlePaste(event) {
        // 获取粘贴的数据
        var items = (event.clipboardData || event.originalEvent.clipboardData).items;
        
        // 遍历粘贴的内容
        for (var i = 0; i < items.length; i++) {
            // 检查是否为图像类型
            if (items[i].type.indexOf("image") !== -1) {
                // 获取图像数据
                var blob = items[i].getAsFile();
                
                this.setFile(blob);
            }
        }
    }

    // 用户更新图片
    handleDrap(event) {
        const files = event.dataTransfer.files; // 获取文件列表
        if(files[0]){
            this.setFile(files[0]);
        }
    }
}


export default Store;