import React, { useEffect, useMemo, useState } from "react";
import styles from './index.module.less';
import { Button, Checkbox, Form, Input, InputNumber, Modal, Space, Tag, Image, Message, Typography } from "@arco-design/web-react";
import { IconDelete, IconEdit, IconEye, IconSync, IconUpload } from "@arco-design/web-react/icon";
import Uploader from "../Uploader";
import Store from './store';
import { Pattern } from "@/types/pattern";
import { useObserver } from "mobx-react-lite";
import { fileSizeText } from "@/utils/file";
import file from "@/store/file";
import ajax from "@/utils/ajax";


interface ImageViewProps {
    data: any;
    onClick: () => void;
    onDelete: () => void;
    onEdit: () => void;
}
const ImageView = ({ data, onClick, onDelete, onEdit }: ImageViewProps) => {
    const o = data;

    const [visible, setVisible] = useState(false)

    return (
        <div key={o.id} className={styles.imageView}>
            <Image
                key={o.id}
                className={styles.image}
                src={o.filePath}
                onClick={(e) => {
                    onClick();
                }}
                title={o.name}
                description={fileSizeText({ size: o.fileSize })}
                actions={[
                    <Button size="mini" type="text" icon={<IconEye />}
                        onClick={() => setVisible(true)}
                    />,
                    <Button size="mini" type="text" icon={<IconEdit />} onClick={onEdit}></Button>,
                    <Button size="mini" type="text" icon={<IconDelete />} onClick={onDelete}></Button>
                ]}
                previewProps={{
                    visible: visible,
                    src: o.filePath,
                    onVisibleChange: (e) => {
                      setVisible(false);
                    },
                }}
            />
            <Typography.Paragraph copyable>/static/{o.fileName}</Typography.Paragraph>
            {/* <div className={styles.fileName} title={o.fileName}>{o.fileName}</div> */}
    </div>
    )
}

interface FileListProps {
    onClick: (item: any) => any;
}
const FileList = (props: FileListProps) => {

    const [store] = useState(() => new Store());


    return useObserver(() => {

        const url = useMemo(() => {
            if(store.oldFile) return URL.createObjectURL(store.oldFile);
            return null;
        },[store.oldFile])

        useEffect(() => {
            store.updateOldFile();
        },[store.file, store.compress, store.maxWidth, store.quality])
        
        const [input, setInput] = useState<string>('');
        const list = useMemo(() => {

            if(input) return file.list.filter((o) => {
                return o.fileName.indexOf(input) !== -1 || o.name && o.name.indexOf(input) !== -1;
            })
            return file.list;
        }, [input, file.list])

        return (
            <React.Fragment>
                <div className={styles.component}>
                    <div className={`${styles.header} flex items-center justify-between	shadow p-2`}>
                        <Space>
                            <Input.Search placeholder="文件搜索" value={input} onChange={setInput} />
                        </Space>
                        <Space>
                            <Button type="primary" icon={<IconUpload />}
                                onClick={() => {
                                    store.setVisible(true);
                                    store.setEditData(null);
                                }}
                            >上传文件</Button>
                            {/* <Button>导入SVG图片</Button> */}
                            <Button icon={<IconSync />}
                                onClick={() => {
                                    store.getList().then(() => {
                                        Message.success("刷新成功")
                                    });
                                }}
                            ></Button>
                            {/* <Button type="primary"
                                onClick={() => {
                                    file.updateFileList();
                                }}
                            >
                                打包
                            </Button> */}
                        </Space>
                    </div>
                    <div className={styles.body}>
                        {list.map((o) => {
                            return (
                                <ImageView data={o} key={o.id}
                                    onClick={() => {
                                        props.onClick(o);
                                    }}
                                    onDelete={() => {
                                        store.deleteFile(o);
                                    }}
                                    onEdit={() => {
                                        store.setVisible(true);
                                        store.setEditData(o);
                                        store.setFileName(o.fileName);
                                        store.setName(o.name);
                                    }}
                                />
                            )
                        })}
                        {[1,2,3,4,5,6,7,8,9].map((o) => {
                            return <div key={`i${o}`} className={styles.imgFill}  />
                        })}
                    </div>
                    <div className={`${styles.footer} flex justify-end shadow p-2`}>
                        <Space>
                            <span>已使用容量：{(file.allSize / (1024 * 1024)).toFixed(2)}/10(M)</span>
                            <span>文件数量：{file.list.length}/100</span>
                        </Space>
                    </div>
                </div>
                <Modal
                    title={store.title}
                    visible={store.visible}
                    onCancel={() => {
                        store.setVisible(false)
                    }}
                    onOk={async () => {
                        if(!store.fileName){
                            return Message.error("文件名不能为空");
                        }
                        
                        if(!store.editData){
                            // 新增
                            if(!store.oldFile) {
                                return Message.error("请上传文件")
                            }
                            // 文件校验
                            await ajax.post('/appfile/verifyFileName',{
                                fileName: store.fileName
                            })
                            await file.verifyFile("create", file);
                            const formData = new FormData();
                            formData.append('file', store.oldFile);
                            formData.append("fileName", store.fileName);
                            formData.append('name', store.name);
                            await ajax.post('/appfile/upload', formData).then(() => {
                                Message.success("文件上传成功");
                                store.setVisible(false);
                                store.getList();
                            });
                        }else {
                            // 编辑
                            const { fileName, id  } = store.editData;
                            if(store.fileName != fileName){
                                // 文件名不一致，需要进行校验
                                await ajax.post('/appfile/verifyFileName',{
                                    fileName: store.fileName
                                })
                            }
                            await file.verifyFile("update", file, store.editData);
                            const formData = new FormData();
                            if(store.oldFile){
                                formData.append('file', store.oldFile);
                            }
                            formData.append("id", id);
                            formData.append("fileName", store.fileName);
                            formData.append('name', store.name);
                            await ajax.post('/appfile/updateFile', formData).then(() => {
                                Message.success("文件更新成功");
                                store.setVisible(false);
                                store.getList();
                            });
                        }

                    }}
                >
                    <Form layout="vertical">
                        <Form.Item
                            label="文件名称"
                            rules={[{ required: true, match: new RegExp(Pattern.iamgeFileName) }]}
                        >
                            <Input value={store.fileName} onChange={store.setFileName} placeholder="请输入文件名"
                                // disabled={Boolean(store.editData)}
                            />
                        </Form.Item>
                        <Form.Item
                            label="文件昵称"
                            extra="只用于文件搜索"
                        >
                            <Input placeholder="请输入文件昵称" value={store.name} onChange={store.setName} />
                        </Form.Item>
                        <Image.PreviewGroup>
                            {store.editData? (
                                <Form.Item label="当前文件">
                                    <Image
                                        width={140}
                                        height={140}
                                        src={store.editData.filePath}
                                        description={fileSizeText({ size: store.editData.fileSize })}
                                    />
                                </Form.Item>
                            ): null}
                        </Image.PreviewGroup>
                        <Form.Item
                            label="上传文件"
                        >
                            {url? (
                                <div>
                                    <Image
                                        width={140}
                                        height={140}
                                        src={url}
                                        description={fileSizeText(store.oldFile)}
                                        alt='lamp'
                                        actions={[
                                            <Button icon={<IconDelete />}
                                                onClick={() => {
                                                    store.clearFile()
                                                }}
                                            ></Button>
                                        ]}
                                        preview={true}
                                    />
                                </div>
                            ): (
                                <React.Fragment>
                                    <div className={styles.trigger}
                                        onDrag={(e) => {
                                            store.handleDrap(e);
                                        }}
                                        onClick={(e) => {
                                            store.onClick();
                                        }}
                                        onPaste={(e) => {
                                            store.handlePaste(e);
                                        }}
                                    >
                                        点击或拖拽文件到此处上传
                                    </div>
                                </React.Fragment>
                            )}
                            <Space>
                                <span><Checkbox checked={store.compress} onChange={store.setCompress} disabled={store.isSvg}>是否压缩</Checkbox></span>
                                {store.compress? (
                                    <span className="flex items-center">
                                        最大宽度
                                        <InputNumber 
                                            className="w-24" min={0} precision={0}
                                            value={store.maxWidth} onChange={store.setMaxWidth}
                                        />
                                    </span>
                                ): null}
                                {/* {store.compress? (
                                    <span className="flex items-center">
                                        压缩精度
                                        <InputNumber
                                            className="w-20" min={0} max={1}
                                            step={0.05}
                                            value={store.quality} onChange={store.setQuality}
                                        />
                                    </span>
                                ): null} */}
                            </Space>
                        </Form.Item>
                    </Form>
                </Modal>
            </React.Fragment>
        )
    })
}


export default FileList;